extends RefCounted
## Bridge smoke runner - runs the headless smoke test from the editor and
## captures the verdict + output so the MCP bridge can report it back.
## Agent-pipeline helper (Nov 3 2026). Not part of the game logic.

func run() -> Dictionary:
	var out: Array = []
	var proj := ProjectSettings.globalize_path("res://")
	var exe := OS.get_executable_path()
	var exit_code := OS.execute(exe, ["--headless", "-s", "tests/smoke_test.gd"], out, true, false, proj)
	var text := "\n".join(PackedStringArray(out))
	var f := FileAccess.open("res://tests/last_smoke_output.txt", FileAccess.WRITE)
	if f:
		f.store_string(text)
		f.close()
	return {"exit_code": exit_code, "lines": out.size(), "output_tail": text.substr(maxi(0, text.length() - 400))}
